import ddw26 from "../data/sources-ddw26.json";
import editions from "../data/sources-editions.json";
import makers from "../data/sources-makers.json";
import venues from "../data/sources-venues.json";

// Sources pages for RN Collins' own packages, one account per package family.
// Page address: /sources/<account>/<slug>. The data files are generated by
// render-kit/sources_export_ours.py (data/sources-<account>.json); do not edit them by hand.
// Ask a Neuroscientist keeps its own data (lib/aan-sources.ts) and its /sources/<mon-dd> addresses.
export type SourceLink = { label: string; url: string };
export type ImageCredit = { where: string; what: string; credit: string; url: string; card: boolean };
export type Origin = { kind: "article" | "listing" | "main"; label: string; url: string } | null;
export type SourcePost = {
  slug: string; date: string; id: string; title: string; series: string; origin: Origin;
  research: SourceLink[]; other: SourceLink[]; images: ImageCredit[];
};
export type Account = {
  key: string; name: string; blurb: string; timeZone: string; posts: SourcePost[];
};

const byDate = (a: SourcePost, b: SourcePost) => a.date.localeCompare(b.date) || a.slug.localeCompare(b.slug);
const sorted = (d: { posts: unknown[] }) => (d.posts as SourcePost[]).slice().sort(byDate);

export const accounts: Account[] = [
  { key: "ddw26", name: "Dutch Design Week 2026", timeZone: "Europe/Amsterdam", posts: sorted(ddw26),
    blurb: "Sets on the Dutch Design Week 2026 programme: the listing, the sources and where each image comes from." },
  { key: "venues", name: "Dutch Design Week venues", timeZone: "Europe/Amsterdam", posts: sorted(venues),
    blurb: "Eindhoven places that host Dutch Design Week, traced through the archive: sources and image credits." },
  { key: "makers", name: "Dutch Design Week makers", timeZone: "Europe/Amsterdam", posts: sorted(makers),
    blurb: "Makers and studios in the Dutch Design Week archive: sources and image credits." },
  { key: "editions", name: "Dutch Design Week editions", timeZone: "Europe/Amsterdam", posts: sorted(editions),
    blurb: "Dutch Design Week year by year, 2015 to 2025: sources and image credits." },
];

export function account(key: string) {
  return accounts.find((a) => a.key === key);
}

export function sourcePost(key: string, slug: string) {
  return account(key)?.posts.find((p) => p.slug === slug);
}

// A page is listed on its account index (and in the sitemap) from its posting day on, in the account's own
// time zone. The page itself exists ahead of time, so the printed address works on posting day.
// SOURCES_LIST_ALL=1 lists every page, for local previews only.
export function listed(a: Account, now = new Date()) {
  if (process.env.SOURCES_LIST_ALL === "1") return a.posts;
  const today = new Intl.DateTimeFormat("en-CA", { timeZone: a.timeZone }).format(now);
  return a.posts.filter((p) => p.date <= today);
}

export function longDate(date: string) {
  return new Date(`${date}T12:00:00Z`).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" });
}

export function host(url: string) {
  try { return new URL(url).hostname.replace(/^www\./, ""); } catch { return ""; }
}

export function entryCount(p: SourcePost) {
  return p.research.length + p.other.length + p.images.length;
}
